input.command:
cat >> src/core/price.ts <<'EOF'

export interface DiscountResult {
  totalCents: number;
  message: string;
}

export function applyLoyaltyDiscount(totalCents: number, customer: Customer): DiscountResult {
  if (customer.orders <= 5) {
    return { totalCents, message: "" };
  }
  const savedCents = Math.round(totalCents * 0.1);
  return {
    totalCents: totalCents - savedCents,
    message: `Loyalty discount: you saved ${formatMoney(savedCents)}`,
  };
}
EOF
sed -i '1i import { formatMoney } from "../api/format.ts";\n' src/core/price.ts
cat >> tests/price.test.ts <<'EOF'

test("more than five orders earns ten percent off", () => {
  const r = applyLoyaltyDiscount(2550, { id: "c1", orders: 6 });
  assert.equal(r.totalCents, 2295);
  assert.equal(r.message, "Loyalty discount: you saved $2.55");
});

test("five orders or fewer earns no discount", () => {
  assert.deepEqual(applyLoyaltyDiscount(2550, { id: "c1", orders: 5 }), { totalCents: 2550, message: "" });
});
EOF
sed -i 's/import { lineTotal, orderTotal }/import { applyLoyaltyDiscount, lineTotal, orderTotal }/' tests/price.test.ts
npm test 2>&1 | tail -15

